// Shared account card on public, customer and admin pages.
(()=>{const nav=document.querySelector('.nav');if(!nav)return;const card=document.createElement('div');card.className='account-card';card.setAttribute('aria-label','حساب المستخدم');const anchor=document.createElement('a');anchor.href='/account?mode=login';anchor.className='account-card-link';const icon=document.createElement('span');icon.className='account-avatar';icon.setAttribute('aria-hidden','true');icon.innerHTML="<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21v-2a8 8 0 0 1 16 0v2\"/></svg>";const info=document.createElement('span');info.className='account-info';const small=document.createElement('small');small.textContent='أهلًا بك في أويس تك';const name=document.createElement('strong');name.textContent='تسجيل الدخول';info.append(small,name);anchor.append(icon,info);const logout=document.createElement('button');logout.type='button';logout.className='account-signout';logout.textContent='تسجيل الخروج';logout.hidden=true;const message=document.createElement('span');message.className='account-feedback';message.setAttribute('role','status');card.append(anchor,logout,message);const actions=nav.querySelector('.nav-actions');if(actions)actions.prepend(card);else nav.append(card);
function render(user){anchor.href=user?(user.role==='admin'?'/admin':'/account'):'/account?mode=login';card.classList.toggle('guest',!user);small.textContent=user?'حسابك':'أهلًا بك في أويس تك';name.textContent=user?user.full_name:'تسجيل الدخول';name.title=user?user.full_name:'';icon.innerHTML="<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" focusable=\"false\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21v-2a8 8 0 0 1 16 0v2\"/></svg>";logout.hidden=!user;card.classList.toggle('signed-in',!!user);anchor.setAttribute('aria-label',user?'فتح حساب '+user.full_name:'تسجيل الدخول أو إنشاء حساب');message.textContent=''}
async function refresh(){try{const r=await fetch('/api/auth/me',{cache:'no-store'});if(r.status===401){render(null);return}if(!r.ok)throw Error();const data=await r.json();render(data.user)}catch{message.textContent='تعذر التحقق من الجلسة';}}
logout.onclick=async()=>{logout.disabled=true;message.textContent='';try{const r=await fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error();render(null);location.assign('/')}catch{message.textContent='تعذر تسجيل الخروج، حاول مجددًا.';logout.disabled=false}};
window.addEventListener('oways:session',event=>render(event.detail));window.addEventListener('pageshow',refresh);render(null);
})();
